out('ECS_L1 completion service', h(P(G + 0x2E28758)))
-- L3 physics worlds and the body getter
for i = 0, 3 do
  local w = P(X + 0x2861D88 + 176 * i)
  local vt = w and P(w)
  local g = vt and P(vt + 136)
  out('ECS_L3 world', i, h(w), 'getter exe offset', h(g and g - X), '(expect 0xD658D0)', 'bodies', h(w and P(w + 24)))
end
-- L2 mission mode and the two managers
local M = P(G + 0x2CE1850)
out('ECS_L2 mode', h(M), 'mission +8', U32(M and M + 8), '+0x40', U32(M and M + 0x40), '(ship: 0 / 2, mission: 1 / 2)')
local function manager(label, slot, corpse)
  local m = P(G + slot)
  if not m then out('ECS_L2', label, 'manager null') return end
  local cap, cnt, act = U32(m + (corpse and 16 or 4)), U32(m + (corpse and 24 or 12)), U32(m + (corpse and 28 or 16))
  out('ECS_L2', label, h(m), 'capacity', cap, 'count', cnt, 'active', act, corpse and '' or ('owned ' .. tostring(U32(m + 20)))
      , '(active <= count <= capacity <= 8192)')
  local ents, rt, sy = P(m + (corpse and 64 or 56)), P(m + 72), P(m + 80)
  local listed, others = {}, {}
  for i = 0, math.min((cnt or 0), corpse and 512 or 2048) - 1 do
    local e = ents and P(ents + 8 * i)
    local pf = e and profile(e)
    if e and not pf then
      local key = h(U32(e)) .. ':' .. h(U32(e + 4))
      others[key] = (others[key] or 0) + 1
    end
    if pf then
      local meta = (not corpse and rt) and (rt + i * 11192 + 11160) or nil
      out('ECS_L2', label, i, pf.name, 'id', U32(e + 8), 'unit', h(U32(e + 12)), 'owned', (U32(e + 20) or 0) % 2,
          corpse and '' or ('bodies ' .. tostring(U32(meta)) .. ' update ' .. tostring(U8(meta + 12)) .. ' sync ' ..
          tostring(U32(sy and sy + i * 432)) .. ' rot ' .. tostring(U32(sy and sy + i * 432 + 184)) .. ' flag ' ..
          tostring(U8(sy and sy + i * 432 + 428))))
      listed[#listed + 1] = {e = e, pf = pf}
    end
  end
  local parts = {}
  for k, v in pairs(others) do parts[#parts + 1] = k .. '=' .. v end
  table.sort(parts)
  out('ECS_L2', label, 'listed', #listed, 'not in the 21 profiles (resource key:variant=count)', table.concat(parts, ' '),
      '(small enemies are expected here; a Charger/Titan/Impaler/Spewer/walker/tripod you killed showing here = its key changed)')
  return listed
end
local units = {}
for _, l in ipairs({manager('ragdoll', 0x2CE1AF8, false) or {}, manager('corpse', 0x2CE1AD8, true) or {}}) do
  for _, u in ipairs(l) do units[#units + 1] = u end
end
-- L4 / L5: one listed unit at a time: registry, skeleton, actors, rows, bodies; compare with the profile
local REG, LISTS, POOLS = P(X + 0x1AB76F8), P(X + 0x286D030), X + 0x2411200
local layers = {}
for n, u in ipairs(units) do
  if n > 6 then break end
  local okk, err = pcall(function()
    local unit = U32(u.e + 12)
    local slot = unit % 0x400000
    local obj = REG and slot < (U32(REG + 0x98) or 0) and P((P(REG + 0x88) or 0) + slot * 8)
    local nodes = obj and U32(obj + 0x70)
    out('ECS_L4 unit', h(unit), u.pf.name, 'object id ok', tostring(obj and U32(obj + 8) == unit), 'nodes', nodes,
        'profile nodes', u.pf.nodes, 'gen', U8((P(REG + 0xA0) or 0) + slot), 'vs', math.floor(unit / 0x400000))
    local list = LISTS and LISTS + slot * 24
    local flags = list and U32(list + 4)
    if not flags or flags % 0x80000000 < 0x40000000 then out('ECS_L4 actor list invalid', h(flags)) return end
    local count = flags % 128
    local handles = (flags >= 0x80000000) and (list + 8) or P(list + 8)
    local mains, aux, aux_ok = 0, 0, 0
    for k = 0, count - 1 do
      local id = U32(handles + 4 * k)
      if id and id ~= 0xFFFFFFFF then
        local pi = (math.floor(id / 0x10000000) % 4) + 10 * math.floor(id / 0x40000000)
        local pool = POOLS + 64 * pi
        local base, cnt, mask, gen, lay = P(pool), U32(pool + 36), U32(pool + 40), U32(pool + 52), U32(pool + 28)
        local ai = bit and bit.band(id, mask or 0) or id % ((mask or 0) + 1)
        local stride, io, doff = lay % 65536, math.floor(lay / 65536) % 256, math.floor(lay / 16777216)
        local row = base + ai * stride
        local data = row + doff
        local owner, fl, bi = U32(data + 12), U32(data + 16), (U32(data + 20) or 0) % 0x1000000
        local name, node, nh = U32(data + 24), U32(data + 28), U32(data + 32)
        local isMain, isAux = false, u.pf.actors[name] ~= nil
        for _, m in ipairs(u.pf.main) do if m == name then isMain = true end end
        if isMain then mains = mains + 1 end
        if isAux then aux = aux + 1; if u.pf.actors[name] == nh then aux_ok = aux_ok + 1 end end
        if (fl or 0) % 2 == 1 then
          local w = P(X + 0x2861D88 + 176 * math.floor(id / 0x40000000))
          local body = w and P(w + 24) and P(w + 24) + 160 * bi
          if body then
            local layer = (U32(body + 108) or 0) % 128
            local key = (isMain and 'main' or (isAux and 'aux' or 'other')) .. ':' .. layer
            layers[key] = (layers[key] or 0) + 1
            if k < 3 then out('ECS_L4 actor', h(id), 'row id ok', tostring(U32(row + io) == id), 'owner ok',
              tostring(owner == unit), 'body id/unit ok', tostring(U32(body + 144) == id and U32(body + 148) == unit),
              'motion', U32(body + 64), 'layer', layer, 'node', node, '<', nodes) end
          end
        end
      end
    end
    out('ECS_L5 unit', u.pf.name, 'actors', count, 'main names found', mains, 'of', #u.pf.main, 'aux mapped', aux,
        'aux node hash equal', aux_ok, '(expect main = profile count; aux node hash equal = aux mapped)')
  end)
  if not okk then out('ECS_L4 unit read failed (race or layout)', tostring(err)) end
end
local parts = {}
for k, v in pairs(layers) do parts[#parts + 1] = k .. '=' .. v end
table.sort(parts)
out('ECS_L4 body layers (kind:layer=count)', table.concat(parts, ' '),
    '(the mod never acts on bodies on layers 52 / 48 / 83 (build 25480438 numbering): expect main / ragdoll bodies '
    .. 'on that set and the repaired aux bodies outside it; anything else means the layer numbering moved)')
-- L4b collision layer names (filter property table): 26088801 has one layer more than 25480438 (103 -> 104)
local FP = P(X + 0x286D338)
local fcount, fnames = FP and U32(FP + 248), FP and P(FP + 256)
local named = {}
for _, i in ipairs({11, 14, 48, 52, 55, 83, 101, 102, 103}) do
  named[#named + 1] = i .. '=' .. h(fnames and fcount and i < fcount and U32(fnames + 4 * i))
end
out('ECS_L4b filter table', h(FP), 'count', fcount, '(expect 104)', 'names', table.concat(named, ' '),
    '(expect 11=0x12D0ABF1 flame, 14=0x4A8FBF9 destructible as in 25480438; record 48/52/83)')
local okk, st = pcall(function() return rawget(_G, 'CorpseCollisionRepair') end)
if okk and type(st) == 'table' then out('ECS_L0 status', st.status, 'getter', st.preflight_getter, 'stops', st.fling_stops,
  'realignments', st.realignments, 'native_waits', st.native_waits)
else out('ECS_L0 CorpseCollisionRepair not visible here; read CorpseCollisionRepair.log') end
